class Solution {
public:
    long long maxPower(vector<int>& stations, int r, int k) {
        int n = stations.size();
        vector<long long> cnt(n + 1);
        for (int i = 0; i < n; i++) {
            int left = max(0, i - r);
            int right = min(n, i + r + 1);
            cnt[left] += stations[i];
            cnt[right] -= stations[i];
        }
        auto check = [&](long long val) -> bool {
            vector<long long> diff = cnt; 
            long long sum = 0;
            long long remaining = k;

            for (int i = 0; i < n; i++) {
                sum += diff[i];
                if (sum < val) {
                    long long add = val - sum;
                    if (remaining < add) {
                        return false;
                    }
                    remaining -= add;
                    int end = min(n, i + 2 * r + 1);
                    diff[end] -= add;
                    sum += add;
                }
            }
            return true;
        };
        long long lo = ranges::min(stations);
        long long hi = accumulate(stations.begin(), stations.end(), 0LL) + k;
        long long res = 0;
        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2;
            if (check(mid)) {
                res = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return res;
    }
};
复杂度分析
时间复杂度：O(nlogD)，其中 n 为数组 stations 的长度，D=sum(stations)+k。计算差分数组需要的时间为 O(n)，二分查找最小电量的最大值的上限即为 D=sum(stations)+k，二分查找每次检测需要的时间为 O(n)，因此总的时间复杂度即为 O(nlogD)。
空间复杂度：O(n)，其中 n 为数组 stations 的长度。计算差分数组需要的空间为 O(n)。

方法一：哈希表 + 哨兵节点
思路及解法
首先将数组中的元素存入哈希表中，由于链表的头节点可能被移除，为了简化代码逻辑，我们在头节点之前添加一个哨兵节点。
从哨兵节点的下一位（即头节点）开始遍历链表，如果当前节点的值存在于哈希表中，则将当前节点移除，否则继续遍历，直到链表遍历完成。
